import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const container = new THREE.Group();

  // Load GLB mesh with machined-metal PBR materials
  const glb = ctx.glbLoader.load(config.meshUrl);
  container.add(glb.scene);

  // Apply scene placement
  if (config.scenePosition) {
    container.position.fromArray(config.scenePosition);
  }
  if (config.rotation) {
    container.rotation.fromArray(config.rotation);
  }
  if (config.scale) {
    container.scale.fromArray(config.scale);
  }

  // Add accent rim light for hero-grade layered depth effect
  const rimLight = new THREE.PointLight(0xff2a38, 1.5, 5);
  rimLight.position.set(1.5, 1.5, 1.5);
  container.add(rimLight);

  // Apply cinematic primitives
  if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach(primitive => {
      if (ctx.primitives && typeof ctx.primitives[primitive.name] === 'function') {
        ctx.primitives[primitive.name](container, primitive.params || {});
      }
    });
  }

  // Weighted-settle entrance animation
  const entranceStartScale = 1.04;
  container.scale.set(entranceStartScale, entranceStartScale, entranceStartScale);

  const entranceTimeline = gsap.timeline();
  entranceTimeline.to(container.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out'
  }, 0);

  // Store base position for hover interactions
  const basePosition = new THREE.Vector3().copy(container.position);

  // Attach event handlers
  container.userData.handlers = {
    hover: () => {
      gsap.to(container.position, {
        y: basePosition.y + 0.15,
        duration: 0.7,
        ease: 'power3.out',
        overwrite: 'auto'
      });
    },
    unhover: () => {
      gsap.to(container.position, {
        y: basePosition.y,
        duration: 0.7,
        ease: 'power3.out',
        overwrite: 'auto'
      });
    },
    click: () => {
      if (container.userData.emit) {
        container.userData.emit('hub-features.select');
      }
    }
  };

  // Cleanup
  container.userData.cleanup = () => {
    entranceTimeline.kill();
    gsap.killTweensOf(container.position);
    gsap.killTweensOf(container.scale);

    glb.scene.traverse(node => {
      if (node.geometry) {
        node.geometry.dispose();
      }
      if (node.material) {
        if (Array.isArray(node.material)) {
          node.material.forEach(m => m.dispose());
        } else {
          node.material.dispose();
        }
      }
    });
  };

  return container;
}
